"""Share of the total score per grade."""
from grades import load_grades


def score_shares(grades):
    """Return each grade's share of the total score, in order."""
    total = sum(x.score for x in grades)
    return [x.score / total for x in grades]


def stored_shares():
    """Shares for the stored grades."""
    return score_shares(load_grades())


def top_share(grades):
    """Return the largest share, or 0.0 when there are no grades."""
    shares = score_shares(grades)
    return max(shares) if shares else 0.0

